import React from "react";
import AddExpense from "./AddExpense";

const Transactions = ({ addTransaction }) => {
  return (
    <div style={{ padding: "20px" }}>
      <h2>Transactions</h2>

      <AddExpense addTransaction={addTransaction} />
    </div>
  );
};

export default Transactions;
